let token=sessionStorage.getItem('cupid-session')||'';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:{Authorization:'Bearer '+token,...(body!==undefined?{'Content-Type':'application/json'}:{})},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error);return data;}
async function run(fn){try{$('#status').textContent='';await fn();}catch(e){$('#status').textContent=e.message;}}
async function refresh(){const me=await api('me');$('#auth').hidden=true;$('#account').hidden=false;$('#identity').textContent='Your account ID: '+me.id;for(const key of ['name','bio','publicHobbies','privateHobbies','attractionThreshold'])$('#profile').elements[key].value=me[key]??'';const [questions,candidates,matches]=await Promise.all([api('questions'),api('candidates'),api('matches')]);const q=questions[0];$('#questions').innerHTML=q?`<p>${esc(q.label)}</p><form id="answer"><select name="value">${(q.type==='boolean'?['Yes','No']:q.type==='scale'?Array.from({length:q.max-q.min+1},(_,i)=>q.min+i):q.options).map(v=>`<option>${esc(v)}</option>`).join('')}</select><button>Answer</button></form>`:'No questions available right now.';if(q)$('#answer').onsubmit=e=>{e.preventDefault();run(async()=>{let value=e.target.elements.value.value;value=q.type==='boolean'?value==='Yes':q.type==='scale'?Number(value):value;await api('answers','POST',{token:q.token,value});await refresh();});};$('#candidates').innerHTML=candidates.map(c=>`<form data-id="${esc(c.id)}"><label>${esc(c.id)} <input name="score" type="number" min="1" max="10" value="${c.score??''}"></label><button>Save rating</button></form>`).join('')||'No other accounts yet.';$('#candidates').querySelectorAll('form').forEach(f=>f.onsubmit=e=>{e.preventDefault();run(async()=>{await api('rating','PUT',{targetId:f.dataset.id,score:f.elements.score.value?Number(f.elements.score.value):null});await refresh();});});$('#matches').innerHTML=matches.map(m=>`<article><h3>${esc(m.name)}</h3><p>${esc(m.bio)}</p><p>${esc(m.publicHobbies)}</p></article>`).join('')||'No mutual matches yet.';}
$('#credentials').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target),session=await api(e.submitter.value,'POST',{username:f.get('username'),password:f.get('password')});token=session.token;sessionStorage.setItem('cupid-session',token);e.target.reset();await refresh();});};
$('#profile').onsubmit=e=>{e.preventDefault();run(async()=>{const body=Object.fromEntries(new FormData(e.target));body.attractionThreshold=Number(body.attractionThreshold);await api('profile','PUT',body);await refresh();});};
$('#tree').onchange=e=>run(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>200000)throw Error('Choose a tree under 200 KB.');await api('tree','PUT',JSON.parse(await f.text()));await refresh();$('#status').textContent='Tree saved.';});
$('#logout').onclick=()=>run(async()=>{await api('logout','POST',{});token='';sessionStorage.removeItem('cupid-session');$('#account').hidden=true;$('#auth').hidden=false;});
if(token)run(refresh);
